mapper.select:
SELECT EXTRACT(MONTH FROM order_date) AS month,
       COALESCE(SUM(total_price), 0) AS current_price
  FROM crm_contract
 WHERE deleted = 0
   AND audit_status = ${@com.lxjl.juling.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
   AND owner_user_id IN

            #{userId}

   AND EXTRACT(YEAR FROM order_date) = #{year}
 GROUP BY EXTRACT(MONTH FROM order_date)

SELECT EXTRACT(MONTH FROM return_time) AS month,
       COALESCE(SUM(price), 0) AS current_price
  FROM crm_receivable
 WHERE deleted = 0
   AND audit_status = ${@com.lxjl.juling.module.crm.enums.common.CrmAuditStatusEnum@APPROVE.status}
   AND owner_user_id IN

            #{userId}

   AND EXTRACT(YEAR FROM return_time) = #{year}
 GROUP BY EXTRACT(MONTH FROM return_time)
